import fs from'node:fs';import{execFileSync}from'node:child_process';
if(process.env.GITHUB_REPOSITORY!=='mstrangtrieueducation-droid/mstrangtrieueducation-droid.github.io')throw Error('REPOSITORY_SCOPE');
const config=JSON.parse(fs.readFileSync(new URL('classes.json',import.meta.url))),allowed=new Set(config.classes.map(c=>c.route));
const paths=execFileSync('git',['status','--porcelain','--untracked-files=all','--',...Array.from(allowed,r=>r+'/data')],{encoding:'utf8'}).split('\n').filter(Boolean).map(line=>line.slice(3)).filter(p=>/\/(?:academic-leaderboard|writing\/(?:[a-f0-9]{64}|asset-[a-f0-9]{64}))\.json$/.test(p));if(!paths.length){console.log('Prepared data unchanged');process.exit(0);}
const api='https://api.github.com/repos/'+process.env.GITHUB_REPOSITORY,headers={Authorization:'Bearer '+process.env.GITHUB_TOKEN,'Content-Type':'application/json'};
async function request(tail,body,method){const r=await fetch(api+tail,{method:method||(body?'POST':'GET'),headers,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('PUBLICATION_HTTP_'+r.status);return r.json();}
const tree=[];let cursor=0;async function upload(){while(cursor<paths.length){const p=paths[cursor++];if(!allowed.has(p.split('/')[0])||p.includes('..'))throw Error('PATH_SCOPE');const data=fs.readFileSync(p),b=await request('/git/blobs',{content:data.toString('base64'),encoding:'base64'});tree.push({path:p,mode:'100644',type:'blob',sha:b.sha});}}await Promise.all([upload(),upload(),upload()]);
// Keep large exports out of GitHub's flat recursive merge, which can return
// 502 for hundreds of image assets. Only the final root commit becomes visible.
async function scopedTree(commit){const base=await request('/git/trees/'+commit.tree.sha),existing=new Map(base.tree.filter(e=>e.type==='tree').map(e=>[e.path,e.sha])),groups=new Map();for(const item of tree){const i=item.path.indexOf('/'),route=item.path.slice(0,i),relative=item.path.slice(i+1);if(!groups.has(route))groups.set(route,[]);groups.get(route).push({...item,path:relative});}const children=[];for(const[route,entries]of groups){const child=await request('/git/trees',{...(existing.has(route)?{base_tree:existing.get(route)}:{}),tree:entries});children.push({path:route,mode:'040000',type:'tree',sha:child.sha});}return request('/git/trees',{base_tree:commit.tree.sha,tree:children});}
// Merge data onto the newest main. Never replace concurrent UI edits or force the branch.
for(let attempt=0;attempt<3;attempt++){const head=(await request('/git/ref/heads/main')).object.sha,c=await request('/git/commits/'+head),t=await scopedTree(c);if((await request('/git/ref/heads/main')).object.sha!==head)continue;const n=await request('/git/commits',{message:'Refresh prepared IELTS dashboard data',tree:t.sha,parents:[head]});await request('/git/refs/heads/main',{sha:n.sha,force:false},'PATCH');await request('/pages/builds',{},'POST');console.log(JSON.stringify({published:tree.length,commit:n.sha}));process.exit(0);}throw Error('CONCURRENT_PUBLICATION');
